//@ run-pass
// PBPK Validation: 3-compartment RK2 model with higher-order accuracy
//
// Model: Gut → Liver (first-pass) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dLiver/dt   = ka * Gut * fa - (Q_h/V_h) * Liver - CL_h * Liver
//   dCentral/dt = (Q_h/V_h) * Liver - ke * Central
//
// Uses RK2 (midpoint method) for 2nd-order accuracy
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.05h, 480 steps (24h)

struct Conc {
    gut: f64,
    liver: f64,
    central: f64
}

struct SimState {
    state: Conc,
    t: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn derivatives(s: Conc) -> Conc {
    let ka = 1.0
    let fa = 0.8
    let q_h = 0.5
    let cl_h = 0.3
    let ke = 0.1
    Conc {
        gut: -ka * s.gut,
        liver: ka * s.gut * fa - q_h * s.liver - cl_h * s.liver,
        central: q_h * s.liver - ke * s.central
    }
}

fn rk2_step(s: Conc, dt: f64) -> Conc {
    // k1 = f(y_n)
    let k1 = derivatives(s)

    // midpoint: y_mid = y_n + 0.5*dt*k1
    let mid = Conc {
        gut: s.gut + 0.5 * dt * k1.gut,
        liver: s.liver + 0.5 * dt * k1.liver,
        central: s.central + 0.5 * dt * k1.central
    }

    // k2 = f(y_mid)
    let k2 = derivatives(mid)

    // y_{n+1} = y_n + dt * k2
    Conc {
        gut: s.gut + dt * k2.gut,
        liver: s.liver + dt * k2.liver,
        central: s.central + dt * k2.central
    }
}

fn main() -> i32 with IO, Div, Mut {
    var sim = SimState {
        state: Conc { gut: 500.0, liver: 0.0, central: 0.0 },
        t: 0.0, auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.05
    var i = 0

    while i < 480 {
        let new_state = rk2_step(sim.state, dt)
        let new_t = sim.t + dt

        // Trapezoidal AUC
        let auc_increment = 0.5 * (sim.state.central + new_state.central) * dt

        var cmax = sim.cmax
        var tmax = sim.tmax
        if new_state.central > sim.cmax {
            cmax = new_state.central
            tmax = new_t
        }

        sim = SimState {
            state: new_state,
            t: new_t,
            auc: sim.auc + auc_increment,
            cmax: cmax,
            tmax: tmax
        }
        i = i + 1
    }

    // Print results
    println(sim.t)
    println(sim.state.gut)
    println(sim.state.liver)
    println(sim.state.central)
    println(sim.auc)
    println(sim.cmax)
    println(sim.tmax)

    // Validate:
    // 1. Time = 24.0h
    if sim.t < 23.9 { return 1 }

    // 2. Gut fully absorbed (exp(-24) ≈ 0)
    if sim.state.gut > 0.01 { return 2 }

    // 3. AUC should be positive and substantial
    if sim.auc < 100.0 { return 3 }

    // 4. Cmax > 0 (drug reached central compartment)
    if sim.cmax < 10.0 { return 4 }

    // 5. Tmax in physiological range (1-8h for oral absorption)
    if sim.tmax < 0.5 { return 5 }
    if sim.tmax > 12.0 { return 6 }

    // 6. All concentrations non-negative (conservation of mass)
    if sim.state.gut < 0.0 { return 7 }
    if sim.state.liver < 0.0 { return 8 }
    if sim.state.central < 0.0 { return 9 }

    // 7. 480 iterations completed
    if i != 480 { return 10 }

    return 0
}

//@ run-pass
// print_f64 must keep magnitude for negatives (not "-0.000000").
// Wave15 Agent B residual closeout for #890 /
// docs/audit/MADAROS_NATIVE_V2_F64_REMAINING_BUGS_2026-07-20.md Note.
// Covered cases: -2.0, -0.5, -0.0 (via 0.0 * -1.0), positive control +2.0.
// Avoid f64_to_bits/bits_to_f64 so the Full Test Suite (lean_single stage2)
// can typecheck; Madaros display path is the surface under test.
// No unary minus — form negatives as 0.0 - x.
//@ expect-stdout: PRINT_F64_NEGATIVE_OK

fn main() -> i32 with IO, Mut, Div, Panic {
    let pos2: f64 = 2.0
    let neg2: f64 = 0.0 - 2.0
    let neg05: f64 = 0.0 - 0.5
    // IEEE754 -0.0 via signed multiply (portable; no bits_to_f64).
    let neg0: f64 = 0.0 * (0.0 - 1.0)

    // Value oracle without bit builtins.
    if pos2 < 1.9 || pos2 > 2.1 {
        print("FAIL pos2 value\n")
        return 1
    }
    if neg2 > 0.0 - 1.9 || neg2 < 0.0 - 2.1 {
        print("FAIL neg2 value\n")
        return 2
    }
    if neg05 > 0.0 - 0.4 || neg05 < 0.0 - 0.6 {
        print("FAIL neg05 value\n")
        return 3
    }
    // -0.0 compares equal to +0.0; check sign via 1.0/x → -inf for -0.0.
    let inv0: f64 = 1.0 / neg0
    if inv0 > 0.0 {
        print("FAIL neg0 not negative zero (1/x positive)\n")
        return 4
    }

    // Display path under test — exact fixed 6-decimal format.
    print("POS2=")
    print_f64(pos2)
    print("\n")
    print("NEG2=")
    print_f64(neg2)
    print("\n")
    print("NEG05=")
    print_f64(neg05)
    print("\n")
    print("NEG0=")
    print_f64(neg0)
    print("\n")

    print("PRINT_F64_NEGATIVE_OK\n")
    0
}

