fn print_csv(data: [f64; 4096], rows: i64, cols: i64) with IO, Mut, Panic, Div {
    // Header row
    var c: i64 = 0
    while c < cols {
        if c > 0 { print(",") }
        print("col_")
        sci_print_i64(c)
        c = c + 1
    }
    println("")

    // Data rows
    var r: i64 = 0
    while r < rows {
        var c2: i64 = 0
        while c2 < cols {
            if c2 > 0 { print(",") }
            sci_print_f64(data[(r * cols + c2) as usize], 6)
            c2 = c2 + 1
        }
        println("")
        r = r + 1
    }
}

fn print_json_matrix(data: [f64; 4096], rows: i64, cols: i64) with IO, Mut, Panic, Div {
    println("[")
    var r: i64 = 0
    while r < rows {
        print("  [")
        var c: i64 = 0
        while c < cols {
            if c > 0 { print(", ") }
            sci_print_f64(data[(r * cols + c) as usize], 6)
            c = c + 1
        }
        if r < rows - 1 {
            println("],")
        } else {
            println("]")
        }
        r = r + 1
    }
    println("]")
}

fn print_epistemic_csv(values: [f64; 4096], uncertainties: [f64; 4096],
                       rows: i64, cols: i64) with IO, Mut, Panic, Div {
