    while c < cols {
        if c > 0 { print(",") }
        print("param_")
        sci_print_i64(c)
        print("_value,param_")
        sci_print_i64(c)
        print("_uncertainty")
        c = c + 1
    }
    println("")

    // Data rows: interleave value and uncertainty for each column
    var r: i64 = 0
    while r < rows {
        var c2: i64 = 0
        while c2 < cols {
            if c2 > 0 { print(",") }
