    var ys: [f64; 1024] = [0.0; 1024]
    var vars: [f64; 1024] = [0.0; 1024]
    var wf: [f64; 1024] = [0.0; 1024]
    var i: i64 = 0
    while i < 5 {
        xs[i as usize] = i as f64
        ys[i as usize] = (i + 1) as f64
        vars[i as usize] = 0.04 + (i as f64) * 0.01
        wf[i as usize] = 400.0 + (i as f64) * 120.0
        i = i + 1
    }

