    let forest = viz_add_forest_plot(&!scene, &ys, &vars, 5, viz_layout_rect(8, 78, 80, 54), viz_style_rgb(170, 180, 255))
    let waterfall = viz_add_waterfall(&!scene, &wf, 5, viz_layout_rect(104, 78, 80, 54), viz_style_rgb(255, 200, 90))

    assert(scatter == 0)
    assert(bars == 1)
    assert(forest == 2)
