    assert(count_nonzero_rect(&c, 104, 8, 80, 54) > 0)
    assert(count_nonzero_rect(&c, 8, 78, 80, 54) > 0)
    assert(count_nonzero_rect(&c, 104, 78, 80, 54) > 0)
    heap_free(c.pixels as *mut i8)

    viz_html_emit_scene(&scene, 200, 150)
